begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_table_privilege('anon','public.seating_tables','select'),'Guests cannot read tables');
select ok(not has_table_privilege('anon','public.seating_assignments','select'),'Guests cannot read assignments');
select ok(not has_table_privilege('authenticated','public.seating_tables','insert'),'Browsers cannot create tables directly');
select ok(not has_table_privilege('authenticated','public.seating_assignments','insert'),'Browsers cannot assign directly');
select ok(not has_function_privilege('anon','public.create_seating_table(text,integer)','execute'),'Anonymous RPC creation blocked');
select ok(not has_function_privilege('authenticated','public.assign_seating_guests(uuid,uuid[])','execute'),'Direct browser assignment RPC blocked');
select ok(not has_function_privilege('authenticated','public.edit_seating_table(uuid,text,integer)','execute'),'Direct browser table edit blocked');
select ok(not has_function_privilege('authenticated','public.delete_seating_table(uuid)','execute'),'Direct browser table delete blocked');
select ok(has_function_privilege('service_role','public.assign_seating_guests(uuid,uuid[])','execute'),'Verified API service may assign');

create temp table people as select n,public.create_invitation('Guest '||n,'',now()+interval '10 days') as link from generate_series(1,5) n;
select public.submit_rsvp(encode(extensions.digest((select link->>'token' from people where n=1),'sha256'),'hex'),'accepted','');
select public.submit_rsvp(encode(extensions.digest((select link->>'token' from people where n=3),'sha256'),'hex'),'declined','');
update public.invitations set archived_at=now() where id=(select (link->>'id')::uuid from people where n=4);
create temp table tables as select public.create_seating_table('Mesa Familia',2) as a,public.create_seating_table('Mesa Amigos',1) as b;
select is((select capacity from public.seating_tables where id=(select (a->>'id')::uuid from tables)),2,'Different capacities persist');
select throws_ok($$select public.create_seating_table('mesa familia',8)$$,'P0001','TABLE_NAME_EXISTS','Case-insensitive duplicate table names rejected');
select throws_ok($$select public.create_seating_table('Mesa Invalid',0)$$,'P0001','INVALID_INPUT','Zero capacity rejected');
select throws_ok($$select public.create_seating_table('Mesa Invalid',101)$$,'P0001','INVALID_INPUT','Unbounded capacity rejected');
select throws_ok($$select public.create_seating_table('M',8)$$,'P0001','INVALID_INPUT','Too-short name rejected');
select public.assign_seating_guests((select (a->>'id')::uuid from tables),(select array_agg((link->>'id')::uuid) from people where n in (1,2)));
select is((select count(*)::integer from public.seating_assignments),2,'Confirmed and pending guests can be assigned together');
select is(jsonb_array_length(public.admin_snapshot()->'seating'->'tables'),2,'Admin snapshot includes tables');
select is(jsonb_array_length(public.admin_snapshot()->'seating'->'assignments'),2,'Admin snapshot includes assignments');
select ok(not (public.resolve_invitation(encode(extensions.digest((select link->>'token' from people where n=1),'sha256'),'hex')) ?| array['seating','tables','table_id','assignments']),'Guest invitation does not expose seating');

insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000000101','seating-admin@example.test'),('00000000-0000-4000-8000-000000000102','non-admin@example.test');
insert into public.admin_profiles(user_id) values ('00000000-0000-4000-8000-000000000101');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000102',true);
set local role authenticated;
select is((select count(*)::integer from public.seating_tables),0,'Non-admin Auth user cannot see tables');
select is((select count(*)::integer from public.seating_assignments),0,'Non-admin Auth user cannot see seating assignments');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000101',true);
set local role authenticated;
select is((select count(*)::integer from public.seating_tables),2,'Admin can read table metadata for Realtime');
select is((select count(*)::integer from public.seating_assignments),2,'Admin can read assignments for Realtime');
reset role;

select lives_ok($$select public.assign_seating_guests((select (a->>'id')::uuid from tables),(select array_agg((link->>'id')::uuid) from people where n in (1,2)))$$,'Assignment retries are idempotent');
select is((select count(*)::integer from public.seating_assignments),2,'No duplicate seats on retry');
select throws_ok($$select public.assign_seating_guests((select (b->>'id')::uuid from tables),array[(select (link->>'id')::uuid from people where n=3)])$$,'P0001','INVITATION_UNAVAILABLE','Declined guests cannot be newly assigned');
select throws_ok($$select public.assign_seating_guests((select (b->>'id')::uuid from tables),array[(select (link->>'id')::uuid from people where n=4)])$$,'P0001','INVITATION_UNAVAILABLE','Archived guests cannot be assigned');
select throws_ok($$select public.assign_seating_guests((select (b->>'id')::uuid from tables),array[(select (link->>'id')::uuid from people where n=1),(select (link->>'id')::uuid from people where n=1)])$$,'P0001','INVALID_INPUT','Duplicate IDs in a group rejected');
select throws_ok($$select public.assign_seating_guests((select (b->>'id')::uuid from tables),'{}'::uuid[])$$,'P0001','INVALID_INPUT','Empty assignment rejected');
select throws_ok($$select public.assign_seating_guests((select (b->>'id')::uuid from tables),array['00000000-0000-4000-8000-000000000099'::uuid])$$,'P0001','NOT_FOUND','Unknown person rejected');
select throws_ok($$select public.assign_seating_guests((select (b->>'id')::uuid from tables),(select array_agg((link->>'id')::uuid) from people where n in (1,2)))$$,'P0001','TABLE_FULL','Over-capacity group move rejected atomically');
select is((select count(*)::integer from public.seating_assignments where table_id=(select (a->>'id')::uuid from tables)),2,'Failed move leaves everyone at the original table');
select is((select count(*)::integer from public.seating_assignments where table_id=(select (b->>'id')::uuid from tables)),0,'Failed group move does not partially fill destination');
select throws_ok($$select public.edit_seating_table((select (a->>'id')::uuid from tables),'Mesa Familia',1)$$,'P0001','TABLE_CAPACITY_TOO_SMALL','Cannot shrink a table below its assigned count');
select lives_ok($$select public.edit_seating_table((select (a->>'id')::uuid from tables),'Mesa Familia',3)$$,'Can increase capacity');
select public.assign_seating_guests((select (a->>'id')::uuid from tables),array[(select (link->>'id')::uuid from people where n=5)]);
select public.assign_seating_guests((select (b->>'id')::uuid from tables),array[(select (link->>'id')::uuid from people where n=1)]);
select is((select count(*)::integer from public.seating_assignments),3,'Moving a person never creates a second seat');
select is((select count(*)::integer from public.seating_assignments where table_id=(select (a->>'id')::uuid from tables)),2,'Move frees source capacity');
select throws_ok($$select public.assign_seating_guests((select (b->>'id')::uuid from tables),array[(select (link->>'id')::uuid from people where n=2)])$$,'P0001','TABLE_FULL','Full destination cannot be overbooked');
select public.assign_seating_guests(null,array[(select (link->>'id')::uuid from people where n=1)]);
select is((select count(*)::integer from public.seating_assignments),2,'Removing a guest frees their seat');
select public.assign_seating_guests((select (a->>'id')::uuid from tables),array[(select (link->>'id')::uuid from people where n=1)]);
select public.submit_rsvp(encode(extensions.digest((select link->>'token' from people where n=2),'sha256'),'hex'),'declined','Changed plans');
select is((select count(*)::integer from public.seating_assignments),3,'Later decline remains visible in the seating plan for review');
select is((select status from public.rsvps where invitation_id=(select (link->>'id')::uuid from people where n=2)),'declined','Current RSVP status is available for the seating UI');
select public.assign_seating_guests(null,array[(select (link->>'id')::uuid from people where n=2)]);
select lives_ok($$select public.edit_seating_table((select (a->>'id')::uuid from tables),'Mesa Familia',2)$$,'Capacity may decrease after releasing seats');
update public.invitations set archived_at=now() where id=(select (link->>'id')::uuid from people where n=5);
select is((select count(*)::integer from public.seating_assignments),1,'Archiving automatically frees the seat');
update public.invitations set archived_at=null where id=(select (link->>'id')::uuid from people where n=5);
select public.assign_seating_guests((select (b->>'id')::uuid from tables),array[(select (link->>'id')::uuid from people where n=5)]);
select public.delete_seating_table((select (b->>'id')::uuid from tables));
select is((select count(*)::integer from public.invitations),5,'Deleting a table preserves all invitations');
select is((select count(*)::integer from public.seating_assignments),1,'Deleting a table releases only its own assignments');
select public.delete_invitation((select (link->>'id')::uuid from people where n=1));
select is((select count(*)::integer from public.seating_assignments),0,'Deleting an invitation cascades to its seat');
create temp table reset_before as select public.admin_reset_preview() as state;
select public.assign_seating_guests((select (a->>'id')::uuid from tables),array[(select (link->>'id')::uuid from people where n=5)]);
select throws_ok($$select public.reset_invitations('BORRAR TODO',(select state->>'version' from reset_before))$$,'P0001','RESET_CHANGED','A seating change invalidates an already prepared invitation reset');
select public.reset_invitations('BORRAR TODO',public.admin_reset_preview()->>'version');
select is((select count(*)::integer from public.seating_assignments),0,'Invitation reset clears seating assignments');
select is((select count(*)::integer from public.seating_tables),1,'Invitation reset preserves table definitions');
select is((select count(*)::integer from public.admin_profiles),1,'Invitation reset preserves administrator access');
select * from finish();
rollback;
